function normalizarTipoEntrada(v) {
  const t = String(v || 'IMEI').toUpperCase().replace(/[^A-Z_]/g, '');
  return ['IMEI', 'LOCK_CODE', 'OUTRO'].includes(t) ? t : 'IMEI';
}
function labelEntradaServico(servico) {
  const tipo = normalizarTipoEntrada(servico?.tipo_entrada);
  if (String(servico?.entrada_label || '').trim()) return String(servico.entrada_label).trim();
  if (tipo === 'LOCK_CODE') return 'Lock Code';
  if (tipo === 'OUTRO') return 'Informação';
  return 'IMEI';
}
function tituloTipoEntrada(tipo) {
  tipo = normalizarTipoEntrada(tipo);
  if (tipo === 'LOCK_CODE') return 'Lock Code';
  if (tipo === 'OUTRO') return 'Outro';
  return 'IMEI';
}
function iconeEntradaServico(servico) {
  const tipo = normalizarTipoEntrada(servico?.tipo_entrada);
  if (tipo === 'LOCK_CODE') return '🔐';
  if (tipo === 'OUTRO') return '📝';
  return '📱';
}
function extrairImeisEmLote(texto) {
  const bruto = String(texto || '').trim();
  if (!bruto) return [];

  // Correção automática: remove tudo que não for número.
  // Aceita 1 IMEI por linha, separado por espaço, vírgula, ponto, traço etc.
  const partes = bruto
    .split(/[\n,;]+/)
    .map(linha => linha.replace(/\D/g, '').trim())
    .filter(Boolean);

  let imeis = [];
  if (partes.length <= 1) {
    const todos = bruto.replace(/\D/g, '');
    if (todos.length > 15 && todos.length % 15 === 0) {
      imeis = todos.match(/.{15}/g) || [];
    } else if (todos) {
      imeis = [todos];
    }
  } else {
    for (const item of partes) {
      if (item.length > 15 && item.length % 15 === 0) {
        imeis.push(...(item.match(/.{15}/g) || []));
      } else {
        imeis.push(item);
      }
    }
  }

  return [...new Set(imeis)];
}
function validarEntradaServico(servico, textoOriginal) {
  const tipo = normalizarTipoEntrada(servico?.tipo_entrada);
  const bruto = String(textoOriginal || '').trim();
  if (tipo === 'IMEI') {
    const imeis = extrairImeisEmLote(bruto);
    if (!imeis.length) return { ok: false, erro: `❌ IMEI inválido.\n\n📱 Envie de 1 até 5 IMEIs.\nCada IMEI precisa ter 15 números.\n\nExemplo:\n356789123456789\n356789123456780` };
    if (imeis.length > 5) return { ok: false, erro: `❌ Limite excedido.\n\nVocê pode enviar no máximo 5 IMEIs por pedido.\nVocê enviou: ${imeis.length}` };

    const invalidos = imeis.filter(i => !/^\d{15}$/.test(i));
    if (invalidos.length) {
      return { ok: false, erro: `❌ IMEI inválido.\n\nOs IMEIs abaixo foram corrigidos automaticamente, mas não ficaram com 15 dígitos:\n${invalidos.join('\n')}\n\nCorrija e tente novamente.` };
    }

    return { ok: true, entradas: imeis };
  }
  if (!bruto || bruto.length < 2) return { ok: false, erro: `❌ ${labelEntradaServico(servico)} inválido.\n\nEnvie a informação solicitada ou digite cancelar.` };
  return { ok: true, entradas: [bruto] };
}
function textoEntradaPedido(pedido) {
  const label = pedido.entrada_label || (normalizarTipoEntrada(pedido.tipo_entrada) === 'LOCK_CODE' ? 'Lock Code' : normalizarTipoEntrada(pedido.tipo_entrada) === 'OUTRO' ? 'Informação' : 'IMEI');
  const valor = pedido.entrada_valor || pedido.imei || '-';
  return `${iconeEntradaServico(pedido)} ${label}: ${valor}`;
}
function today() { return new Date().toISOString().slice(0, 10); }
function dateBR(v) { if (!v) return '-'; const d = new Date(v); return isNaN(d) ? String(v) : d.toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }); }
function extrairImeisCancelamento(texto) {
  const encontrados = String(texto || '').match(/\b\d{15}\b/g) || [];
  return Array.from(new Set(encontrados)).slice(0, 10);
}
async function localizarPedidosCancelaveis(revendaId, imeis) {
  const resultados = [];
  for (const imei of imeis) {
    // V129: procura primeiro o pedido PENDENTE do próprio cliente. Antes o código
    // pegava apenas o último pedido do IMEI e podia ignorar um PENDENTE válido.
    const pedido = await get(`SELECT p.*,
        CASE WHEN EXISTS (
          SELECT 1 FROM servicos_catalogo sx
          WHERE sx.cancelamento_permitido=1
            AND (sx.id=p.servico_id OR lower(trim(sx.nome))=lower(trim(p.servico_nome)))
        ) THEN 1 ELSE 0 END AS cancelamento_permitido
      FROM pedidos p
      WHERE p.revenda_id=? AND p.imei=? AND upper(trim(p.status))='PENDENTE'
      ORDER BY p.id DESC LIMIT 1`, [revendaId, imei]);
    if (!pedido) {
      const outro = await get(`SELECT p.* FROM pedidos p WHERE p.revenda_id=? AND p.imei=? ORDER BY p.id DESC LIMIT 1`, [revendaId, imei]);
      resultados.push({ imei, pedido: outro || undefined, motivo: outro ? 'STATUS' : 'NAO_ENCONTRADO' });
      continue;
    }
    if (!Number(pedido.cancelamento_permitido || 0)) { resultados.push({ imei, pedido, motivo: 'NAO_PERMITIDO' }); continue; }
    const existente = await get(`SELECT id, status FROM solicitacoes_cancelamento WHERE pedido_id=?`, [pedido.id]);
    if (existente) { resultados.push({ imei, pedido, motivo: 'JA_SOLICITADO' }); continue; }
    resultados.push({ imei, pedido, motivo: 'OK' });
  }
  return resultados;
}
function textoConfirmacaoCancelamento(resultados) {
  const ok = resultados.filter(r => r.motivo === 'OK');
  if (!ok.length) return '❌ Nenhum serviço pendente disponível para cancelamento.';
  let t = `🔄 *CANCELAMENTO*\n\n`;
  ok.forEach((r, i) => {
    t += `*${i+1}️⃣ ${r.imei}*\n${r.pedido.servico_nome || '-'}\n📅 ${dateBR(r.pedido.enviado_em || r.pedido.criado_em)}\n\n`;
  });
  t += `Deseja cancelar ${ok.length > 1 ? `estes *${ok.length} serviços*` : 'este serviço'}?\n\n1️⃣ ✅ Confirmar cancelamento\n2️⃣ ❌ Voltar`;
  return t.trim();
}

async function cancelarPedidosAutomaticamentePeloCliente(cliente, resultados) {
  const cancelados = [];
  let totalEstornado = 0;

  for (const r of resultados.filter(x => x.motivo === 'OK')) {
    // V128: revalida tudo no instante da confirmação para evitar corrida de status.
    const atual = await get(`SELECT p.*,
        CASE WHEN EXISTS (
          SELECT 1 FROM servicos_catalogo sx
          WHERE sx.cancelamento_permitido=1
            AND (sx.id=p.servico_id OR lower(trim(sx.nome))=lower(trim(p.servico_nome)))
        ) THEN 1 ELSE 0 END AS cancelamento_permitido
      FROM pedidos p
      WHERE p.id=? AND p.revenda_id=? LIMIT 1`, [r.pedido.id, cliente.id]);

    if (!atual) continue;
    if (String(atual.status || '').toUpperCase() !== 'PENDENTE') continue;
    if (!Number(atual.cancelamento_permitido || 0)) continue;

    const resultado = await cancelarPedidoComEstorno(atual.id, 'Cancelado pelo próprio cliente');
    if (!resultado?.ok || resultado.jaCancelado) continue;

    try {
      await run(`INSERT OR IGNORE INTO solicitacoes_cancelamento
        (pedido_id, revenda_id, imei, servico_id, servico_nome, status, solicitado_em, processado_em)
        VALUES (?, ?, ?, ?, ?, 'CANCELADO', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)`,
        [atual.id, cliente.id, atual.imei || atual.entrada_valor || r.imei, atual.servico_id, atual.servico_nome]);
      await run(`UPDATE solicitacoes_cancelamento
        SET status='CANCELADO', processado_em=CURRENT_TIMESTAMP
        WHERE pedido_id=?`, [atual.id]);
    } catch (_) {}

    cancelados.push({ pedido: resultado.pedido || atual, estornou: !!resultado.estornou, valor: Number(resultado.valor || 0) });
    if (resultado.estornou) totalEstornado += Number(resultado.valor || 0);
  }

  if (cancelados.length) {
    const linhas = cancelados.map(x => `• ${x.pedido.imei || x.pedido.entrada_valor || '-'} — ${x.pedido.servico_nome || '-'}`).join('\n');
    await enviarParaAdmins(`❌ *Cancelamento realizado pelo cliente*\n\n👤 Cliente: ${cliente.nome || '-'}\n📦 Quantidade: ${cancelados.length}\n\n${linhas}${totalEstornado > 0 ? `\n\n💰 Total estornado: ${brl(totalEstornado)}` : ''}\n\n🏢 Centralunlocker`, 'CANCELADO');
  }

  return { cancelados, totalEstornado };
}

