// ===== V163 — Dhru Reseller API (exclusivo) =====
const DHRU_SECRET_FILE = path.join(DATA_DIR, 'dhru-reseller-secret.key');
function dhruCryptoKey() {
  try {
    if (!fs.existsSync(DHRU_SECRET_FILE)) {
      fs.mkdirSync(path.dirname(DHRU_SECRET_FILE), { recursive: true });
      fs.writeFileSync(DHRU_SECRET_FILE, crypto.randomBytes(32), { mode: 0o600 });
    }
    const k = fs.readFileSync(DHRU_SECRET_FILE);
    if (k.length === 32) return k;
  } catch (e) { console.log('⚠️ Chave local Dhru:', e.message); }
  return crypto.createHash('sha256').update(String(ADMIN_PANEL_PASS || 'centralunlocker') + '|dhru-v163').digest();
}
function dhruEncrypt(valor) {
  const iv=crypto.randomBytes(12), key=dhruCryptoKey();
  const cipher=crypto.createCipheriv('aes-256-gcm',key,iv);
  const enc=Buffer.concat([cipher.update(String(valor),'utf8'),cipher.final()]);
  const tag=cipher.getAuthTag();
  return ['v1',iv.toString('base64'),tag.toString('base64'),enc.toString('base64')].join(':');
}
function dhruDecrypt(valor) {
  try {
    const [v,ivb,tagb,encb]=String(valor||'').split(':');
    if(v!=='v1') return '';
    const d=crypto.createDecipheriv('aes-256-gcm',dhruCryptoKey(),Buffer.from(ivb,'base64'));
    d.setAuthTag(Buffer.from(tagb,'base64'));
    return Buffer.concat([d.update(Buffer.from(encb,'base64')),d.final()]).toString('utf8');
  } catch(_) { return ''; }
}
function dhruMask(t){ t=String(t||''); return t?`${'•'.repeat(Math.min(12,Math.max(6,t.length-4)))}${t.slice(-4)}`:'Não configurado'; }
function dhruNormalizeBaseUrl(u){ return String(u||'').trim().replace(/\/+$/,''); }
async function dhruToken(){ return dhruDecrypt(await getConfig('dhru_token_enc','')); }
async function dhruBaseUrl(){ return dhruNormalizeBaseUrl(await getConfig('dhru_base_url','')); }
async function dhruApiPrefix(){ return 'api/reseller/v1'; }
async function dhruCallbackSecret(){
  let v=await getConfig('dhru_callback_secret','');
  if(!v){ v=crypto.randomBytes(24).toString('hex'); await setConfig('dhru_callback_secret',v); }
  return v;
}
async function dhruPublicBase(){ return dhruNormalizeBaseUrl(await getConfig('dhru_public_base_url', process.env.RENDER_EXTERNAL_URL || process.env.PUBLIC_URL || '')); }
function dhruBuildUrl(base,prefix,endpoint){
  const ep=String(endpoint||'').replace(/^\/+/, '');
  const pr=String(prefix||'').replace(/^\/+|\/+$/g,'');
  return `${base}${pr?'/'+pr:''}/${ep}`;
}
async function dhruRawRequest(method, url, token, data=null, params=null){
  return axios({method,url,data,params,timeout:90000,headers:{Authorization:`Bearer ${token}`,Accept:'application/json','Content-Type':'application/json'},validateStatus:s=>s>=200&&s<300});
}
async function dhruRequest(method, endpoint, data=null, params=null){
  const base=await dhruBaseUrl(), token=await dhruToken(), prefix=await dhruApiPrefix();
  if(!base) throw new Error('URL da API Dhru não configurada no painel.');
  if(!token) throw new Error('Token Dhru não configurado no painel.');
  let url=dhruBuildUrl(base,prefix,endpoint);
  if((await getConfig('dhru_force_trailing_slash','0'))==='1' && !url.endsWith('/')) url+='/';
  const r=await dhruRawRequest(method,url,token,data,params);
  return r.data;
}
async function dhruTestOfficialApi(){
  const base=await dhruBaseUrl(), token=await dhruToken();
  if(!base) throw new Error('URL da API Dhru não configurada no painel.');
  if(!token) throw new Error('Access Token/Bearer Token Dhru não configurado no painel.');
  const prefix='api/reseller/v1';
  const accountUrl=dhruBuildUrl(base,prefix,'account');
  const productsUrl=dhruBuildUrl(base,prefix,'products');
  const account=(await dhruRawRequest('get',accountUrl,token)).data||{};
  if(String(account?.status||'').toLowerCase()==='error') throw new Error(account?.message||'Erro ao consultar conta Dhru');
  const products=(await dhruRawRequest('get',productsUrl,token)).data||{};
  if(String(products?.status||'').toLowerCase()==='error') throw new Error(products?.message||'Erro ao consultar produtos Dhru');
  await setConfig('dhru_api_prefix',prefix);
  await setConfig('dhru_last_account_url',accountUrl);
  await setConfig('dhru_last_products_url',productsUrl);
  return {prefix,account,products,accountUrl,productsUrl};
}
function dhruProductsFromPayload(payload){
  const data=payload?.data||payload||{};
  const products=data.products||{};
  if(Array.isArray(products)) return products.map((v,i)=>[String(v.product_uuid||v.uuid||v.id||i),v]);
  return Object.entries(products||{});
}
function dhruCategoriesFromPayload(payload){
  const raw=payload?.data?.categories || payload?.categories || {};
  if(Array.isArray(raw)){
    const out={};
    raw.forEach((c,i)=>{
      if(!c) return;
      const id=String(c.id||c.cid||c.uuid||c.code||`C${i+1}`);
      out[id]=typeof c==='string'?{name:c}:c;
    });
    return out;
  }
  return raw&&typeof raw==='object'?raw:{};
}
// V179: separação técnica da API Dhru em IMEI / Remote / File / Server Service.
function dhruServiceType(product){
  const vals=[product?.service_type,product?.serviceType,product?.type,product?.product_type,product?.productType,product?.group_type,product?.groupType]
    .map(v=>String(v??'').trim().toLowerCase()).filter(Boolean);
  const joined=vals.join(' ');
  if(/remote/.test(joined)) return 'REMOTE_SERVICE';
  if(/file/.test(joined)) return 'FILE_SERVICE';
  if(/server/.test(joined)) return 'SERVER_SERVICE';
  if(/imei/.test(joined)) return 'IMEI_SERVICE';
  const fields=Array.isArray(product?.fields)?product.fields:[];
  const fn=fields.map(f=>String(f?.name||'').toLowerCase()).join(' ');
  if(/imei|meid|serial|sn\b|lock code|unlock code/.test(fn)) return 'IMEI_SERVICE';
  if(/file|upload|attachment/.test(fn)) return 'FILE_SERVICE';
  const text=[product?.name,product?.category,product?.group,product?.description].map(v=>String(v||'').toLowerCase()).join(' ');
  if(/remote|teamviewer|anydesk/.test(text)) return 'REMOTE_SERVICE';
  if(/file|firmware|upload/.test(text)) return 'FILE_SERVICE';
  if(/server/.test(text)) return 'SERVER_SERVICE';
  return 'IMEI_SERVICE';
}
function dhruServiceTypeMeta(tipo){
  const m={
    IMEI_SERVICE:{label:'IMEI Service',icon:'📱'},
    REMOTE_SERVICE:{label:'Remote Service',icon:'💻'},
    FILE_SERVICE:{label:'File Service',icon:'📁'},
    SERVER_SERVICE:{label:'Server Service',icon:'🌐'}
  };
  return m[String(tipo||'').toUpperCase()]||m.IMEI_SERVICE;
}
function dhruCategoryNames(product,cats){
  const cids=Array.isArray(product?.cids)?product.cids.map(String):[];
  const names=cids.map(cid=>{
    const c=cats?.[cid];
    if(typeof c==='string') return c;
    return c?.name||c?.title||c?.label||cid;
  }).map(x=>String(x||'').trim()).filter(Boolean);
  return [...new Set(names)];
}
function dhruUserFields(product){
  const fields=Array.isArray(product?.fields)?product.fields:[];
  return fields.filter(f=>{
    const n=String(f?.name||'').toLowerCase();
    return !['feedback_url','reference_id','quantity'].includes(n);
  });
}
function dhruFieldSummary(product){
  const fs=dhruUserFields(product);
  if(!fs.length) return 'Nenhum dado adicional';
  return fs.map(f=>`${f.required?'*':''}${f.name}`).join(', ');
}
function dhruTipoEntrada(product){
  const fs=dhruUserFields(product).filter(f=>f.required!==false);
  return fs.length===1 && String(fs[0].name||'').toUpperCase()==='IMEI' ? 'IMEI' : 'OUTRO';
}
function dhruEntradaLabel(product){
  const fs=dhruUserFields(product).filter(f=>f.required!==false);
  if(fs.length===1) return String(fs[0].name||'Dados');
  return fs.length ? `Dados: ${fs.map(f=>f.name).join(' / ')}`.slice(0,180) : 'Dados do pedido';
}

// V175: apresentação em português no WhatsApp, preservando nomes/campos originais da API Dhru.
function dhruCampoLabelPt(nome){
  const raw=String(nome||'').trim();
  const k=raw.toLowerCase().replace(/[_-]+/g,' ').replace(/\s+/g,' ').trim();
  const mapa={
    'imei':'IMEI','lock code':'Código de Bloqueio','unlock code':'Código de Desbloqueio',
    'serial number':'Número de Série','serial':'Número de Série','sn':'Número de Série',
    'email':'E-mail','e mail':'E-mail','username':'Usuário','user name':'Usuário','user':'Usuário',
    'password':'Senha','phone number':'Número de Telefone','mobile number':'Número de Telefone',
    'model':'Modelo','model name':'Nome do Modelo','manufacturer':'Fabricante','carrier':'Operadora',
    'network':'Rede / Operadora','country':'País','status':'Situação','quantity':'Quantidade',
    'order id':'Número do Pedido','reference id':'Referência do Pedido','account':'Conta',
    'code':'Código','pin':'PIN','meid':'MEID','udid':'UDID','icloud':'iCloud','frp':'FRP'
  };
  return mapa[k]||raw;
}
function dhruCampoIconePt(nome){
  const k=String(nome||'').toLowerCase();
  if(k.includes('imei')||k.includes('model')) return '📱';
  if(k.includes('lock')||k.includes('unlock')||k==='code'||k.includes('pin')) return '🔐';
  if(k.includes('serial')||k==='sn'||k.includes('meid')||k.includes('udid')) return '🔢';
  if(k.includes('mail')) return '📧';
  if(k.includes('user')||k.includes('account')) return '👤';
  if(k.includes('phone')||k.includes('mobile')) return '📞';
  if(k.includes('country')) return '🌎';
  if(k.includes('carrier')||k.includes('network')) return '📡';
  return '📝';
}
