function dhruValorPt(valor){
  const raw=String(valor??'').trim();
  const k=raw.toLowerCase();
  const mapa={
    'blacklisted':'BLOQUEADO','clean':'LIMPO','blocked':'BLOQUEADO','unblocked':'DESBLOQUEADO',
    'locked':'BLOQUEADO','unlocked':'DESBLOQUEADO','done':'CONCLUÍDO','completed':'CONCLUÍDO',
    'success':'SUCESSO','processing':'EM PROCESSO','pending':'PENDENTE','rejected':'REJEITADO',
    'failed':'FALHOU','yes':'SIM','no':'NÃO','true':'SIM','false':'NÃO','brazil':'Brasil',
    'stolen or lost':'Roubado ou Perdido','lost or stolen':'Perdido ou Roubado'
  };
  return mapa[k]??raw;
}
function dhruChaveResultadoPt(chave){
  const raw=String(chave||'').trim();
  const k=raw.toLowerCase().replace(/[_-]+/g,' ').replace(/\s+/g,' ').trim();
  const mapa={
    'model':'Modelo','model name':'Nome do Modelo','manufacturer':'Fabricante','blacklist status':'Situação da Blacklist',
    'general list status':'Situação Geral','blacklist records':'Registros de Blacklist','blacklisted by':'Bloqueado por',
    'blacklisted on':'Data do Bloqueio','blacklist reason':'Motivo do Bloqueio','country':'País','carrier':'Operadora',
    'network':'Rede / Operadora','status':'Situação','serial number':'Número de Série','serial':'Número de Série',
    'unlock code':'Código de Desbloqueio','lock code':'Código de Bloqueio','result':'Resultado','message':'Mensagem',
    'device is clean':'Aparelho está limpo','clean status':'Situação Clean','sim lock':'Bloqueio de SIM',
    'purchase country':'País de Compra','activation status':'Situação da Ativação','warranty status':'Situação da Garantia'
  };
  return mapa[k]||dhruCampoLabelPt(raw);
}
function traduzirResultadoDhruPt(v){
  const limpo=limparResultadoDhru(v);
  if(!limpo) return '';
  return limpo.split('\n').map(linha=>{
    const m=linha.match(/^\s*([^:]{1,80})\s*:\s*(.*)$/);
    if(!m) return dhruValorPt(linha);
    return `${dhruChaveResultadoPt(m[1])}: ${dhruValorPt(m[2])}`;
  }).join('\n').replace(/\bBlacklisted\b/gi,'BLOQUEADO').replace(/\bClean\b/gi,'LIMPO');
}
function dhruFieldsUsuario(product){
  return (product?.fields||[]).filter(f=>!['feedback_url','reference_id','quantity'].includes(String(f?.name||'').toLowerCase()));
}
function dhruSerializarCampos(campos,valores){
  if(campos.length===1) return String(valores?.[0]??'').trim();
  return campos.map((f,i)=>`${f.name}: ${String(valores?.[i]??'').trim()}`).filter(l=>!/:\s*$/.test(l)).join('\n');
}
function dhruParseEntradaParaExibicao(product,entrada){
  const fs=dhruFieldsUsuario(product);
  const txt=String(entrada||'').trim();
  if(!fs.length) return txt?`📝 Informação: ${txt}`:'';
  if(fs.length===1 && !txt.includes(':')) return `${dhruCampoIconePt(fs[0].name)} ${dhruCampoLabelPt(fs[0].name)}: ${txt}`;
  const map={};
  for(const line of txt.split(/\r?\n/)){
    const m=line.match(/^([^:=]+)\s*[:=]\s*(.*)$/); if(m) map[m[1].trim().toLowerCase()]=m[2].trim();
  }
  return fs.map(f=>{const v=map[String(f.name||'').toLowerCase()];return v?`${dhruCampoIconePt(f.name)} ${dhruCampoLabelPt(f.name)}: ${v}`:''}).filter(Boolean).join('\n') || txt;
}
async function dhruEntradaPedidoPt(servico,pedidoOuEntrada){
  const p=await dhruProductForService(servico.id||servico.servico_id);
  const entrada=typeof pedidoOuEntrada==='object'?(pedidoOuEntrada.entrada_valor||pedidoOuEntrada.imei||''):pedidoOuEntrada;
  return dhruParseEntradaParaExibicao(p,entrada);
}
async function textoSaldoInsuficienteDhru(revenda,valor,servico,entradas=[]){
  const saldo=Number(revenda?.saldo||0), falta=Math.max(0,Number(valor||0)-saldo);
  const p=await dhruProductForService(servico.id);
  const dados=(Array.isArray(entradas)?entradas:[entradas]).map(e=>dhruParseEntradaParaExibicao(p,e)).filter(Boolean).join('\n');
  return `❌ Saldo insuficiente\n\n🛠 Serviço: ${nomeServicoWhatsApp(servico)}${dados?`\n${dados}`:''}\n\n💰 Valor: ${brl(valor)}\n💳 Saldo: ${brl(saldo)}\n💵 Falta: ${brl(falta)}\n\n1️⃣ Pagar este serviço\n2️⃣ Adicionar saldo\n3️⃣ Cancelar pedido\n\n💬 Digite o número da opção.`;
}
function dhruPromptCampo(f,idx,total){
  const opcional=f?.required===false?'\n\nEste campo é opcional. Digite *pular* para continuar.':'';
  return `${dhruCampoIconePt(f?.name)} Informe ${dhruCampoLabelPt(f?.name)}:${total>1?`\n\nCampo ${idx+1} de ${total}`:''}${opcional}`;
}

// V176: precificação Dhru por porcentagem, categoria e preço manual.
async function dhruConfigPrecificacao(){
  return {
    margemPadrao: Math.max(0, Number(await getConfig('dhru_margem_padrao','30'))||0),
    usdBrl: Math.max(0, Number(await getConfig('dhru_usd_brl','0'))||0),
    autoReprice: String(await getConfig('dhru_auto_reprice','1'))==='1'
  };
}
function dhruCustoEmBrl(custo,currency,usdBrl){
  const c=Math.max(0,Number(custo)||0), moeda=String(currency||'').trim().toUpperCase();
  if(!c) return 0;
  if(!moeda||moeda==='BRL'||moeda==='R$') return c;
  if(moeda==='USD'||moeda==='$') return usdBrl>0?c*usdBrl:null;
  return null;
}
function dhruPrecoAutomatico(custo,currency,margem,usdBrl){
  const base=dhruCustoEmBrl(custo,currency,usdBrl);
  if(base===null) return null;
  return Math.round((base*(1+(Math.max(0,Number(margem)||0)/100)))*100)/100;
}
async function dhruMargemCategoria(nome){
  const r=await get(`SELECT margin_pct FROM dhru_category_pricing WHERE category=?`,[String(nome||'').trim()]);
  return r&&r.margin_pct!==null&&r.margin_pct!==undefined?Math.max(0,Number(r.margin_pct)||0):null;
}
async function dhruRecalcularPrecoServico(servicoId){
  const r=await get(`SELECT d.custo,d.currency,d.categorias_json,d.categoria,s.api_price_mode,s.api_margin_pct FROM dhru_products d JOIN servicos_catalogo s ON s.id=d.catalogo_id WHERE s.id=? AND s.api_provider='DHRU'`,[servicoId]);
  if(!r||String(r.api_price_mode||'MANUAL').toUpperCase()!=='AUTO') return null;
  let categorias=[];try{categorias=JSON.parse(r.categorias_json||'[]')}catch(_){};
  if(!Array.isArray(categorias)||!categorias.length) categorias=String(r.categoria||'Sem categoria').split(' / ').map(x=>x.trim()).filter(Boolean);
  const cfg=await dhruConfigPrecificacao();
  const margemServico=r.api_margin_pct!==null&&r.api_margin_pct!==undefined?Math.max(0,Number(r.api_margin_pct)||0):null;
  const margemCategoria=await dhruMargemCategoria(categorias[0]||'Sem categoria');
  const margem=margemServico!==null?margemServico:(margemCategoria!==null?margemCategoria:cfg.margemPadrao);
  const preco=dhruPrecoAutomatico(r.custo,r.currency,margem,cfg.usdBrl);
  if(preco===null) return null;
  await run(`UPDATE servicos_catalogo SET preco_padrao=? WHERE id=?`,[preco,servicoId]);
  return {preco,margem};
}
async function dhruRecalcularTodosAutomaticos(){
  const ids=await all(`SELECT id FROM servicos_catalogo WHERE api_provider='DHRU' AND UPPER(COALESCE(api_price_mode,'MANUAL'))='AUTO' ORDER BY id`);
  let atualizados=0,ignorados=0;
  for(const x of ids){const r=await dhruRecalcularPrecoServico(x.id);if(r)atualizados++;else ignorados++;}
  return {atualizados,ignorados};
}

async function sincronizarProdutosDhru(){
  const payload=await dhruRequest('get','/products');
  const cats=dhruCategoriesFromPayload(payload);
  const entries=dhruProductsFromPayload(payload);
  const currency=String(payload?.data?.currency||payload?.currency||'').trim();
  const precCfg=await dhruConfigPrecificacao();
  const margensRows=await all(`SELECT category,margin_pct FROM dhru_category_pricing`);
  const margensCat=new Map(margensRows.map(x=>[String(x.category||''),Math.max(0,Number(x.margin_pct)||0)]));
  let sincronizados=0,novos=0;
  for(const [uuid,prod] of entries){
    if(!uuid||!prod) continue;
    const nome=String(prod.name||`Dhru ${uuid}`).trim();
    const custo=Number(prod.price||0)||0;
    const cids=Array.isArray(prod.cids)?prod.cids.map(String):[];
    const categorias=dhruCategoryNames(prod,cats);
    const categoria=categorias.join(' / ') || 'Sem categoria';
    const campos=dhruFieldSummary(prod);
    const serviceType=dhruServiceType(prod);
    const descricao=`Produto sincronizado automaticamente da API Dhru. Campos: ${campos}`;
    const tipo=dhruTipoEntrada(prod), label=dhruEntradaLabel(prod);
    const existente=await get(`SELECT * FROM servicos_catalogo WHERE api_provider='DHRU' AND api_service_id=?`,[uuid]);
    const margemCat=margensCat.has(categorias[0]||'')?margensCat.get(categorias[0]||''):precCfg.margemPadrao;
    const precoAuto=dhruPrecoAutomatico(custo,currency,margemCat,precCfg.usdBrl);
    let catalogoId=existente?.id||null;
    const nomePt=dhruNomeServicoPt(nome);
    if(!existente){
      const ins=await run(`INSERT INTO servicos_catalogo (nome,preco_padrao,tipo_entrada,entrada_label,categoria,descricao,prazo,ativo,api_provider,api_service_id,api_cost,api_auto,api_price_mode,api_margin_pct,api_manual_price,nome_exibicao)
        VALUES (?,?,?,?,?,?,'Automático via Dhru',0,'DHRU',?,?,1,'AUTO',NULL,NULL,?)`,[nome,precoAuto===null?0:precoAuto,tipo,label,categoria,descricao,uuid,custo,nomePt]);
      catalogoId=ins.lastID; novos++;
    } else {
      const modo=String(existente.api_price_mode||'MANUAL').toUpperCase();
      const margemServico=existente.api_margin_pct!==null&&existente.api_margin_pct!==undefined?Math.max(0,Number(existente.api_margin_pct)||0):null;
      const precoAtualizado=(modo==='AUTO'&&precCfg.autoReprice)?dhruPrecoAutomatico(custo,currency,margemServico!==null?margemServico:margemCat,precCfg.usdBrl):null;
      await run(`UPDATE servicos_catalogo SET nome=?,tipo_entrada=?,entrada_label=?,categoria=?,descricao=?,prazo='Automático via Dhru',api_cost=?,api_auto=1,nome_exibicao=CASE WHEN TRIM(COALESCE(nome_exibicao,''))='' THEN ? ELSE nome_exibicao END${precoAtualizado!==null?',preco_padrao=?':''} WHERE id=?`,precoAtualizado!==null?[nome,tipo,label,categoria,descricao,custo,nomePt,precoAtualizado,existente.id]:[nome,tipo,label,categoria,descricao,custo,nomePt,existente.id]);
    }
    // V181: categorias novas já nascem com apresentação em português, sem sobrescrever edição manual.
    for(const catOriginal of categorias){
      const catPt=categoriaWhatsAppPt(catOriginal,'DHRU');
      await run(`INSERT OR IGNORE INTO dhru_category_display(category,display_name,atualizado_em) VALUES (?,?,CURRENT_TIMESTAMP)`,[catOriginal,catPt]);
    }
    await run(`INSERT OR REPLACE INTO dhru_products (product_uuid,nome,categoria,custo,currency,fields_json,raw_json,catalogo_id,cids_json,categorias_json,service_type,atualizado_em) VALUES (?,?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP)`,[uuid,nome,categoria,custo,currency,JSON.stringify(prod.fields||[]),JSON.stringify(prod),catalogoId,JSON.stringify(cids),JSON.stringify(categorias),serviceType]);
    sincronizados++;
  }
  await setConfig('dhru_ultima_sync',new Date().toISOString());
  await setConfig('dhru_currency',currency);
  return {sincronizados,novos,total:entries.length,currency};
}
async function dhruProductForService(servicoId){
  const r=await get(`SELECT d.* FROM dhru_products d JOIN servicos_catalogo s ON s.id=d.catalogo_id WHERE s.id=? AND s.api_provider='DHRU'`,[servicoId]);
  if(!r) return null;
  try { r.fields=JSON.parse(r.fields_json||'[]'); } catch(_){ r.fields=[]; }
  try { r.raw=JSON.parse(r.raw_json||'{}'); } catch(_){ r.raw={}; }
  return r;
}
function dhruParseInput(product, entrada){
  const fields=(product?.fields||[]).filter(f=>!['feedback_url','reference_id','quantity'].includes(String(f?.name||'').toLowerCase()));
  const required=fields.filter(f=>f.required!==false);
  const txt=String(entrada||'').trim();
  const out={};
  if(required.length<=1 && fields.length<=1){
    if(fields[0]) out[fields[0].name]=txt;
    return out;
  }
  const lines=txt.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
  for(const line of lines){
    const m=line.match(/^([^:=]+)\s*[:=]\s*(.+)$/);
    if(m) out[m[1].trim().toLowerCase()]=m[2].trim();
  }
  const final={};
  for(const f of fields){
    const key=String(f.name||'');
    const val=out[key.toLowerCase()];
    if(val!==undefined) final[key]=val;
  }
  const missing=required.filter(f=>!String(final[f.name]??'').trim());
  if(missing.length) throw new Error(`Dados obrigatórios ausentes: ${missing.map(f=>f.name).join(', ')}`);
  return final;
}
async function textoEntradaDhru(servico){
  const p=await dhruProductForService(servico.id);
  if(!p) return `${iconeEntradaServico(servico)} Informe o ${labelEntradaServico(servico)}:`;
  const fs=(p.fields||[]).filter(f=>!['feedback_url','reference_id','quantity'].includes(String(f?.name||'').toLowerCase()));
  if(fs.length<=1) return dhruPromptCampo(fs[0]||{name:labelEntradaServico(servico)},0,1);
  return `📋 Envie os dados abaixo, *um por linha*, usando exatamente este formato:\n\n${fs.map(f=>`${f.name}: ${f.required===false?'(opcional)':'...'}`).join('\n')}\n\nExemplo:\n${fs.map(f=>`${f.name}: exemplo`).join('\n')}`;
}
async function executarPedidoDhru(pedidoId){
  const pedido=await get(`SELECT p.*,s.api_provider,s.api_service_id FROM pedidos p LEFT JOIN servicos_catalogo s ON s.id=p.servico_id WHERE p.id=?`,[pedidoId]);
  if(!pedido||pedido.api_provider!=='DHRU'||!pedido.api_service_id) return {executado:false};
  const ja=await get(`SELECT * FROM dhru_orders WHERE pedido_id=? AND status NOT IN ('ERRO_ENVIO','REJEITADO') ORDER BY id DESC LIMIT 1`,[pedido.id]);
  if(ja) return {executado:true,jaExiste:true};
  const product=await dhruProductForService(pedido.servico_id);
  if(!product) throw new Error('Produto Dhru não encontrado localmente. Sincronize os serviços.');
  let campos;
  try { campos=dhruParseInput(product,pedido.entrada_valor||pedido.imei||''); }
  catch(e){
    await run(`UPDATE pedidos SET status='CANCELADO',motivo_cancelamento=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?`,[e.message,pedido.id]);
    throw e;
  }
  const pub=await dhruPublicBase(), secret=await dhruCallbackSecret();
  if(pub) campos.feedback_url=`${pub}/api/dhru/feedback?secret=${encodeURIComponent(secret)}`;
  campos.reference_id=String(pedido.id);
  if(campos.Quantity===undefined && campos.quantity===undefined) campos.Quantity=1;
  const payload=[{product_uuid:pedido.api_service_id,fields:[campos]}];
  const ins=await run(`INSERT INTO dhru_orders (pedido_id,revenda_id,product_uuid,reference_id,status,request_json) VALUES (?,?,?,?, 'ENVIANDO',?)`,[pedido.id,pedido.revenda_id,pedido.api_service_id,String(pedido.id),JSON.stringify(payload)]);
  try{
    const resp=await dhruRequest('post','/order',payload);
    if(String(resp?.status||'').toLowerCase()==='error') throw new Error(resp?.message||'A API Dhru rejeitou o pedido');
    // A API oficial pode retornar data como array simples OU array aninhado (lotes).
    // Achata de forma segura para localizar o pedido pelo reference_id.
    const flattenDhruData=(v)=>{
      if(!Array.isArray(v)) return v==null?[]:[v];
      return v.flatMap(x=>Array.isArray(x)?flattenDhruData(x):[x]);
    };
    const arr=flattenDhruData(resp?.data).filter(Boolean);
    const data=arr.find(x=>String(x?.reference_id||'')===String(pedido.id))||arr[0]||{};
    const orderUuid=String(data?.order_uuid||data?.order_id||'').trim();

    // status=success / code=200 significa que o fornecedor ACEITOU o pedido.
    // Algumas instalações não retornam order_uuid imediatamente, mas o feedback_url
    // ainda envia reference_id + order_id depois. NUNCA estornar um pedido aceito.
    const apiOk=String(resp?.status||'').toLowerCase()==='success' || Number(resp?.code)===200;
    if(!orderUuid && !apiOk) throw new Error(resp?.message||'A API Dhru não confirmou o envio do pedido');

    await run(`UPDATE dhru_orders SET status=?,order_uuid=?,response_json=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?`,[orderUuid?'ENVIADO':'AGUARDANDO_FEEDBACK',orderUuid,JSON.stringify(resp),ins.lastID]);
    await run(`UPDATE pedidos SET status='EM PROCESSO',atualizado_em=CURRENT_TIMESTAMP WHERE id=?`,[pedido.id]);
    console.log(`✅ DHRU pedido ${pedido.id} aceito pelo fornecedor${orderUuid?' | '+orderUuid:' | aguardando feedback'}`);
    return {executado:true,sucesso:true,orderUuid:orderUuid||null,aguardandoFeedback:!orderUuid,resposta:resp};
  } catch(e){
    const detalhe=String(e?.response?.data?.message||e?.response?.data?.detail||e.message||'Falha na API Dhru').slice(0,1000);
    await run(`UPDATE dhru_orders SET status='ERRO_ENVIO',erro=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?`,[detalhe,ins.lastID]);
    const atual=await get('SELECT * FROM pedidos WHERE id=?',[pedido.id]);
    if(atual?.revenda_id && Number(atual.cobrado||0)===1){
      await run('UPDATE revendas SET saldo=saldo+?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?',[Number(atual.valor||0),atual.revenda_id]);
      await run(`UPDATE pedidos SET cobrado=0,estornado=1,status='CANCELADO',motivo_cancelamento=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?`,[`Falha automática Dhru: ${detalhe}`,pedido.id]);
    } else await run(`UPDATE pedidos SET status='CANCELADO',motivo_cancelamento=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?`,[`Falha automática Dhru: ${detalhe}`,pedido.id]);
    const cliente=pedido.revenda_id?await get('SELECT * FROM revendas WHERE id=?',[pedido.revenda_id]):null;
    if(cliente) await enviarParaCanaisCliente(cliente,`⚠️ O pedido não pôde ser enviado ao fornecedor.\n\n🛠 ${pedido.servico_nome}\n\nO valor foi estornado quando aplicável.`,pedido.revenda_jid||'');
    throw e;
  }
}
function dhruDecodeReplay(v){
  const s=String(v||'');
  if(!s) return '';
  try { const b=Buffer.from(s,'base64').toString('utf8'); if(b && /[\x20-\x7E\u00A0-\uFFFF]/.test(b)) return b; } catch(_){}
  return s;
}
function limparResultadoDhru(v){
  let s=String(v||'');
  if(!s) return '';
  // Preserva quebras de linha úteis antes de remover tags HTML do retorno do fornecedor.
  s=s.replace(/<\s*br\s*\/?\s*>/gi,'\n')
     .replace(/<\s*\/\s*(p|div|li|tr|h[1-6])\s*>/gi,'\n')
     .replace(/<\s*li(?:\s[^>]*)?>/gi,'• ')
     .replace(/<\s*td(?:\s[^>]*)?>/gi,' ')
     .replace(/<[^>]+>/g,'');
  const entities={amp:'&',lt:'<',gt:'>',quot:'"',apos:"'",nbsp:' '};
  s=s.replace(/&(#x?[0-9a-f]+|amp|lt|gt|quot|apos|nbsp);/gi,(m,e)=>{
    const k=String(e).toLowerCase();
    if(entities[k]!==undefined) return entities[k];
    if(k[0]==='#'){
      const hex=k[1]==='x';
      const n=parseInt(k.slice(hex?2:1),hex?16:10);
      return Number.isFinite(n)?String.fromCodePoint(n):m;
    }
    return m;
  });
  return s.replace(/\r/g,'').replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n').trim();
}
// A Dhru aceita reference_id numérico. Reservamos a faixa 900000000+ para
// consultas internas do Desbloqueio TIM, evitando conflito com pedidos normais.
const TIM_UNLOCK_REF_BASE=900000000;
function timUnlockReference(pedidoId){
  const id=Number(pedidoId)||0;
  return id>0?String(TIM_UNLOCK_REF_BASE+id):'';
}
function timUnlockPedidoIdFromReference(ref){
  const n=Number(String(ref||'').trim());
  if(!Number.isInteger(n)||n<=TIM_UNLOCK_REF_BASE) return 0;
  const id=n-TIM_UNLOCK_REF_BASE;
  return Number.isInteger(id)&&id>0?id:0;
}

function timUnlockIsDesbloqueioTim(pedido){ return normalizarNomeServico(pedido?.servico_nome||'')==='desbloqueio tim'; }
function timUnlockImei(pedido){ const v=String(pedido?.imei||pedido?.entrada_valor||'').replace(/\D/g,''); return /^\d{15}$/.test(v)?v:''; }
async function timUnlockDhruProduct(){
  const uuid=String(await getConfig('tim_unlock_dhru_product_uuid','')).trim();
  if(!uuid) return null;
  return await get(`SELECT d.*,s.id AS catalogo_id,s.nome AS catalogo_nome,s.nome_exibicao,s.ativo FROM dhru_products d LEFT JOIN servicos_catalogo s ON s.id=d.catalogo_id WHERE d.product_uuid=?`,[uuid]);
}
async function executarConsultaAutomaticaDesbloqueioTim(pedidoId,{force=false}={}){
  const pedido=await get('SELECT * FROM pedidos WHERE id=?',[pedidoId]);
  if(!pedido||!timUnlockIsDesbloqueioTim(pedido)) return {executado:false,motivo:'nao_desbloqueio_tim'};
  const imei=timUnlockImei(pedido); if(!imei) return {executado:false,motivo:'imei_invalido'};
  const produto=await timUnlockDhruProduct(); if(!produto) return {executado:false,motivo:'consulta_nao_configurada'};
  let fields=[]; try{fields=JSON.parse(produto.fields_json||'[]')}catch(_){}
  const userFields=fields.filter(f=>!['feedback_url','reference_id','quantity'].includes(String(f?.name||'').toLowerCase()));
  const imeiField=userFields.find(f=>String(f?.name||'').toLowerCase()==='imei');
  if(!imeiField) return {executado:false,motivo:'produto_sem_imei'};
  const anterior=await get('SELECT * FROM tim_unlock_dhru_checks WHERE pedido_id=?',[pedidoId]);
  if(anterior&&!force&&!['ERRO_ENVIO','REJEITADO'].includes(String(anterior.status||'').toUpperCase())) return {executado:true,jaExiste:true};
  if(anterior&&force) await run('DELETE FROM tim_unlock_dhru_checks WHERE pedido_id=?',[pedidoId]);
  const campos={}; campos[String(imeiField.name||'IMEI')]=imei;
  const pub=await dhruPublicBase(),secret=await dhruCallbackSecret();
  if(pub) campos.feedback_url=`${pub}/api/dhru/feedback?secret=${encodeURIComponent(secret)}`;
  campos.reference_id=timUnlockReference(pedidoId); campos.Quantity=1;
  const payload=[{product_uuid:produto.product_uuid,fields:[campos]}];
  await run(`INSERT INTO tim_unlock_dhru_checks (pedido_id,product_uuid,status,request_json) VALUES (?,?,'ENVIANDO',?)`,[pedidoId,produto.product_uuid,JSON.stringify(payload)]);
  try{
    const resp=await dhruRequest('post','/order',payload);
    if(String(resp?.status||'').toLowerCase()==='error') throw new Error(resp?.message||'A API Dhru rejeitou a consulta interna');
    const arr=[];(function walk(x){if(Array.isArray(x))x.forEach(walk);else if(x&&typeof x==='object')arr.push(x)})(resp?.data);
    const data=arr.find(x=>String(x?.reference_id||'')===timUnlockReference(pedidoId))||arr[0]||{};
    const orderUuid=String(data?.order_uuid||data?.order_id||'').trim();
    const accepted=String(resp?.status||'').toLowerCase()==='success'||Number(resp?.code||0)===200||/submitted|success|accepted/i.test(String(resp?.message||''))||!!orderUuid;
    if(!accepted) throw new Error(resp?.message||'Consulta interna não confirmada');
    await run(`UPDATE tim_unlock_dhru_checks SET status=?,order_uuid=?,response_json=?,atualizado_em=CURRENT_TIMESTAMP WHERE pedido_id=?`,[orderUuid?'ENVIADO':'AGUARDANDO_FEEDBACK',orderUuid,JSON.stringify(resp),pedidoId]);
    return {executado:true,orderUuid};
  }catch(e){
    await run(`UPDATE tim_unlock_dhru_checks SET status='ERRO_ENVIO',erro=?,atualizado_em=CURRENT_TIMESTAMP WHERE pedido_id=?`,[String(e?.response?.data?.message||e.message||e),pedidoId]);
    console.log('❌ DHRU TIM AUTO:',pedidoId,e?.response?.status||'',e?.response?.data?.message||e.message);
    return {executado:false,erro:e.message};
  }
}
async function processarFeedbackTimUnlock(body){
  const pedidoId=timUnlockPedidoIdFromReference(body?.reference_id); if(!pedidoId) throw new Error('reference_id TIM inválido');
  const status=String(body?.status||'').toLowerCase();
  const orderId=String(body?.order_id||body?.order_uuid||'');
  const replay=dhruDecodeReplay(body?.replay||body?.reply||body?.result||body?.message||'');
  const falha=['rejected','reject','failed','failure','cancelled','canceled'].includes(status);
  const concluido=['success','completed','complete','done'].includes(status);
  await run(`UPDATE tim_unlock_dhru_checks SET order_uuid=COALESCE(NULLIF(?,''),order_uuid),status=?,feedback_json=?,resultado_original=CASE WHEN ?<>'' THEN ? ELSE resultado_original END,erro=?,atualizado_em=CURRENT_TIMESTAMP WHERE pedido_id=?`,[orderId,falha?'REJEITADO':concluido?'CONCLUIDO':(status.toUpperCase()||'PROCESSANDO'),JSON.stringify(body),replay,replay,falha?replay:'',pedidoId]);
  notificarPainel('pedido','🔎 Consulta automática Desbloqueio TIM',`Pedido #${pedidoId} — ${concluido?'concluída':falha?'falhou':'em processo'}`);
  return {pedidoId,status,replay,interno:true};
}
function timUnlockResultadoEstruturado(raw){
  const txt=limparResultadoDhru(raw||'');
  const linhas=txt.split(/\n+/).map(x=>x.trim()).filter(Boolean),pares=[];
  for(const l of linhas){const m=l.match(/^([^:]+):\s*(.*)$/);if(m)pares.push([m[1].trim(),m[2].trim()]);}
  const first=names=>{for(const [k,v] of pares){if(names.includes(k.toLowerCase()))return v}return ''};
  const eventos=[];
  for(let i=0;i<pares.length;i++){
    const [k,v]=pares[i],kl=k.toLowerCase();
    if(kl==='blacklisted by'||kl==='removed by'){
      const ev={tipo:kl==='removed by'?'REMOVIDO':'BLOQUEADO',operadora:v,pais:'',data:'',motivo:''};
      for(let j=i+1;j<Math.min(pares.length,i+5);j++){
        const [kk,vv]=pares[j],x=kk.toLowerCase(); if(x==='blacklisted by'||x==='removed by') break;
        if(x.includes('country'))ev.pais=vv; else if(x.endsWith(' on'))ev.data=vv; else if(x.includes('reason'))ev.motivo=vv;
      }
      eventos.push(ev);
    }
  }
  return {modelo:first(['model','model name']),status:first(['blacklist status']),geral:first(['general list status']),registros:first(['blacklist records']),eventos,raw:txt};
}
function timUnlockResultadoHtml(check){
  if(!check) return '<div class="muted">Consulta automática ainda não criada.</div>';
  const st=String(check.status||'PENDENTE').toUpperCase();
  if(st!=='CONCLUIDO') return `<div><b>${['REJEITADO','ERRO_ENVIO'].includes(st)?'🔴 Falhou':'🟡 Em processo'}</b>${check.erro?`<br><span class="muted">${safeHtml(check.erro)}</span>`:''}</div>`;
  const d=timUnlockResultadoEstruturado(check.resultado_original||'');
  const ev=d.eventos.map((e,i)=>`<div style="border-top:1px solid #374151;padding-top:8px;margin-top:8px"><b>${i+1}º registro — ${e.tipo==='REMOVIDO'?'🟢 Removido':(i>0?'🔴 Bloqueado novamente':'🔴 Bloqueado')}</b><br>Operadora: ${safeHtml(e.operadora||'-')}<br>País: ${safeHtml(dhruValorPt(e.pais||'-'))}<br>Data: ${safeHtml(e.data||'-')}<br>Motivo: ${safeHtml(dhruValorPt(e.motivo||'-'))}</div>`).join('');
  const atual=d.eventos.length?(d.eventos[d.eventos.length-1].tipo==='REMOVIDO'?'🟢 FORA DA BLACKLIST':'🔴 BLACKLIST TIM'):(/blacklisted/i.test(d.status)?'🔴 BLACKLIST':'—');
  return `<b>Aparelho:</b> ${safeHtml(d.modelo||'-')}<br><b>Status Blacklist:</b> ${safeHtml(dhruValorPt(d.status||'-'))}<br><b>Lista geral:</b> ${safeHtml(dhruValorPt(d.geral||'-'))}<br><b>Registros encontrados:</b> ${safeHtml(d.registros||String(d.eventos.length))}<br><br><b>📋 Histórico de Blacklist</b>${ev||'<div class="muted">Nenhum evento estruturado.</div>'}<br><br><b>Situação atual: ${safeHtml(atual)}</b>`;
}
function timUnlockPedidoConsultaInline(o){
  const c=o?._timDhru||null;
  const colsp=10; // tabela de Desbloqueio TIM: seleção + ID + entrada + cliente + contato + valor + status + data + nota + ações
  if(!c){
    return `<tr class="tim-dhru-inline"><td colspan="${colsp}"><div class="card" style="margin:8px 0"><b>🔎 Consulta Dhru</b><p class="muted" style="margin:6px 0">Este pedido ainda não possui consulta interna.</p><form class="forms-inline" method="post" action="/admin/pedido/${o.id}/dhru-tim-check"><button class="btn green">🔎 CHECK</button></form></div></td></tr>`;
  }
  const st=String(c.status||'PENDENTE').toUpperCase();
  const podeCheck=['REJEITADO','ERRO_ENVIO'].includes(st);
  const acoes=`<a class="btn gray" href="/admin/pedido/${o.id}/dhru-tim-original">Ver retorno original</a> ${podeCheck?`<form class="forms-inline" method="post" action="/admin/pedido/${o.id}/dhru-tim-check"><button class="btn green">🔎 CHECK</button></form>`:`<form class="forms-inline" method="post" action="/admin/pedido/${o.id}/dhru-tim-refazer"><button class="btn orange" onclick="return confirm('Refazer a consulta interna deste IMEI?')">🔄 Refazer consulta</button></form>`}`;
  return `<tr class="tim-dhru-inline"><td colspan="${colsp}"><div class="card" style="margin:8px 0"><b>🔎 Consulta Dhru — Pedido #${o.id}</b><p><b>IMEI:</b> ${safeHtml(o.imei||o.entrada_valor||'-')}</p>${timUnlockResultadoHtml(c)}<div style="margin-top:12px">${acoes}</div></div></td></tr>`;
}

async function processarFeedbackDhru(body){
  const reference=String(body?.reference_id||'').trim();
  if(timUnlockPedidoIdFromReference(reference)) return processarFeedbackTimUnlock(body);
  if(!reference) throw new Error('reference_id ausente');
  const pedidoId=Number(reference); if(!pedidoId) throw new Error('reference_id inválido');
  const pedido=await get('SELECT * FROM pedidos WHERE id=?',[pedidoId]);
  if(!pedido) throw new Error('pedido não encontrado');
  const status=String(body?.status||'').toLowerCase();
  const orderId=String(body?.order_id||body?.order_uuid||'');
  const replay=dhruDecodeReplay(body?.replay||body?.reply||body?.message||'');
  await run(`UPDATE dhru_orders SET order_uuid=COALESCE(NULLIF(?,''),order_uuid),status=?,feedback_json=?,resultado=?,atualizado_em=CURRENT_TIMESTAMP WHERE pedido_id=?`,[orderId,status.toUpperCase()||'ATUALIZADO',JSON.stringify(body),replay,pedidoId]);
  const cliente=pedido.revenda_id?await get('SELECT * FROM revendas WHERE id=?',[pedido.revenda_id]):null;
  if(['success','completed','complete','done'].includes(status)){
    const jaFinalizado=String(pedido.status).toUpperCase()==='FINALIZADO';
    if(!jaFinalizado) await finalizarPedido(pedido,{notificarCliente:false});
    if(cliente && !jaFinalizado){
      const clienteAtual=await get('SELECT * FROM revendas WHERE id=?',[pedido.revenda_id]);
      const resultadoLimpo=traduzirResultadoDhruPt(replay);
      const servicoAtual=await get('SELECT * FROM servicos_catalogo WHERE id=?',[pedido.servico_id]);
      const dadosPt=servicoAtual?await dhruEntradaPedidoPt(servicoAtual,pedido):`${dhruCampoIconePt(pedido.entrada_label||'Entrada')} ${dhruCampoLabelPt(pedido.entrada_label||'Entrada')}: ${pedido.entrada_valor||pedido.imei||'-'}`;
      const saldoLinha=clienteAtual?`\n\n💳 Saldo: ${brl(clienteAtual.saldo||0)}`:'';
      await enviarParaCanaisCliente(clienteAtual||cliente,`✅ *SERVIÇO CONCLUÍDO*\n\n🛠 Serviço: ${servicoAtual?nomeServicoWhatsApp(servicoAtual):dhruNomeServicoPt(pedido.servico_nome)}\n${dadosPt}\n💰 Valor: ${brl(pedido.valor)}${resultadoLimpo?`\n\n📄 *RESULTADO*\n${resultadoLimpo}`:''}${saldoLinha}`,pedido.revenda_jid||'');
    }
  } else if(['rejected','reject','failed','failure','cancelled','canceled'].includes(status)){
    const atual=await get('SELECT * FROM pedidos WHERE id=?',[pedidoId]);
    if(atual?.revenda_id && Number(atual.cobrado||0)===1 && Number(atual.estornado||0)!==1){
      await run('UPDATE revendas SET saldo=saldo+?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?',[Number(atual.valor||0),atual.revenda_id]);
      await run(`UPDATE pedidos SET cobrado=0,estornado=1,status='CANCELADO',motivo_cancelamento=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?`,[`Dhru: ${status}${replay?' - '+replay:''}`,pedidoId]);
    } else await run(`UPDATE pedidos SET status='CANCELADO',motivo_cancelamento=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?`,[`Dhru: ${status}${replay?' - '+replay:''}`,pedidoId]);
    const servicoRejeitado=await get('SELECT * FROM servicos_catalogo WHERE id=?',[pedido.servico_id]);
    if(cliente) await enviarParaCanaisCliente(cliente,`❌ *Serviço rejeitado*\n\n🛠 ${servicoRejeitado?nomeServicoWhatsApp(servicoRejeitado):dhruNomeServicoPt(pedido.servico_nome)}${replay?`\n📄 Motivo: ${traduzirResultadoDhruPt(replay)}`:''}\n\n💰 O valor foi estornado quando aplicável.`,pedido.revenda_jid||'');
  }
  return {pedidoId,status,replay};
}

async function consultarPedidoDhru(orderUuid){
  if(!orderUuid) throw new Error('order_uuid ausente');
  const resp=await dhruRequest('get','/order',null,{order_uuid:orderUuid});
  if(String(resp?.status||'').toLowerCase()==='error') throw new Error(resp?.message||'Erro ao consultar pedido Dhru');
  return resp;
}

let dhruPollEmExecucao=false;
async function acompanharPedidosDhru(){
  if(dhruPollEmExecucao) return;
  dhruPollEmExecucao=true;
  try{
    const pendentes=await all(`SELECT * FROM dhru_orders WHERE status IN ('ENVIADO','PROCESSANDO','AGUARDANDO_FEEDBACK') AND COALESCE(order_uuid,'')<>'' ORDER BY id ASC LIMIT 30`);
    for(const row of pendentes){
      try{
        const resp=await consultarPedidoDhru(row.order_uuid);
        const d=resp?.data||{};
        const st=String(d?.status||'').toLowerCase();
        await run(`UPDATE dhru_orders SET status=?,response_json=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?`,[(st||'PROCESSANDO').toUpperCase(),JSON.stringify(resp),row.id]);
        if(['rejected','reject','failed','failure','cancelled','canceled'].includes(st)){
          await processarFeedbackDhru({reference_id:row.reference_id,order_id:row.order_uuid,status:st,replay:d?.replay||d?.reply||d?.message||''});
        } else if(['success','completed','complete','done'].includes(st)){
          const replay=d?.replay||d?.reply||d?.result||d?.message||'';
          if(replay){
            await processarFeedbackDhru({reference_id:row.reference_id,order_id:row.order_uuid,status:st,replay});
          } else {
            await run(`UPDATE dhru_orders SET status='AGUARDANDO_FEEDBACK',atualizado_em=CURRENT_TIMESTAMP WHERE id=?`,[row.id]);
          }
        } else {
          await run(`UPDATE pedidos SET status='EM PROCESSO',atualizado_em=CURRENT_TIMESTAMP WHERE id=? AND status NOT IN ('FINALIZADO','CANCELADO')`,[row.pedido_id]);
        }
      }catch(e){ console.log('⚠️ DHRU STATUS',row.order_uuid,e?.response?.status||'',e?.response?.data?.message||e.message); }
    }
    const timPendentes=await all(`SELECT * FROM tim_unlock_dhru_checks WHERE status IN ('ENVIADO','PROCESSANDO','AGUARDANDO_FEEDBACK') AND COALESCE(order_uuid,'')<>'' ORDER BY id ASC LIMIT 30`);
    for(const row of timPendentes){
      try{
        const resp=await consultarPedidoDhru(row.order_uuid),d=resp?.data||{},st=String(d?.status||'').toLowerCase();
        await run(`UPDATE tim_unlock_dhru_checks SET status=?,response_json=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?`,[(st||'PROCESSANDO').toUpperCase(),JSON.stringify(resp),row.id]);
        if(['rejected','reject','failed','failure','cancelled','canceled','success','completed','complete','done'].includes(st)){
          const replay=d?.replay||d?.reply||d?.result||d?.message||'';
          if(replay||['rejected','reject','failed','failure','cancelled','canceled'].includes(st)) await processarFeedbackTimUnlock({reference_id:timUnlockReference(row.pedido_id),order_id:row.order_uuid,status:st,replay});
        }
      }catch(e){ console.log('⚠️ DHRU TIM STATUS',row.order_uuid,e?.response?.status||'',e?.response?.data?.message||e.message); }
    }
  }finally{ dhruPollEmExecucao=false; }
}


function notificarPainel(tipo, titulo, mensagem) {
  try {
    const n = { tipo, titulo, mensagem, hora: new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }) };
    if (io && typeof io.emit === 'function') {
      io.emit('notificacao', n);
      io.emit('dashboard-update', { at: Date.now() });
    }
    console.log('🔔 PAINEL:', titulo, mensagem || '');
  } catch (e) {
    console.log('⚠️ notificarPainel:', e.message);
  }
}

// Atualiza, em tempo real, somente as telas ligadas ao fluxo Bloqueio TIM.
// Esta função era chamada pelas rotas do painel, mas não existia no arquivo.
// O ReferenceError acontecia depois de salvar a baixa no SQLite e encerrava o
// processo Node, fazendo o Render exibir 502 até concluir o reinício.
function emitirAtualizacaoBloqueioTim(acao = 'atualizacao', pedidoId = null) {
  try {
    if (io && typeof io.emit === 'function') {
      io.emit('bloqueio-tim-update', {
        acao: String(acao || 'atualizacao'),
        pedidoId: pedidoId == null ? null : Number(pedidoId),
        at: Date.now()
      });
      io.emit('dashboard-update', { at: Date.now() });
    }
  } catch (e) {
    // Uma falha de atualização visual nunca pode derrubar o servidor nem
    // desfazer uma alteração que já foi gravada no banco.
    console.log('⚠️ emitirAtualizacaoBloqueioTim:', e.message);
  }
}

async function columnExists(table, col) {
  const cols = await all(`PRAGMA table_info(${table})`);
  return cols.some(c => c.name === col);
}
async function addColumnIfMissing(table, col, definition) {
  if (!(await columnExists(table, col))) await run(`ALTER TABLE ${table} ADD COLUMN ${col} ${definition}`);
}

