async function precoDaRevenda(revendaId, servicoId) {
  const pr = await get('SELECT preco FROM precos_revenda WHERE revenda_id=? AND servico_id=?', [revendaId, servicoId]);
  if (pr && Number(pr.preco) > 0) return Number(pr.preco);
  const s = await get('SELECT preco_padrao FROM servicos_catalogo WHERE id=?', [servicoId]);
  return Number(s?.preco_padrao || 0);
}
async function modalidadeServicoRevenda(revendaId, servicoId) {
  const cfg = await get('SELECT modalidade FROM modalidades_servico_revenda WHERE revenda_id=? AND servico_id=?', [revendaId, servicoId]);
  if (cfg?.modalidade) return normalizarTipoRevenda(cfg.modalidade);
  // Compatibilidade com clientes antigos que ainda não possuem uma linha por
  // serviço. Novas configurações do painel sempre gravam a modalidade acima.
  const r = await get('SELECT tipo_revenda FROM revendas WHERE id=?', [revendaId]);
  return normalizarTipoRevenda(r?.tipo_revenda || 'PRE_PAGO');
}
async function modalidadeEsimRevenda(revenda) {
  // Sempre consulta o banco quando temos o ID. Assim uma alteração feita no
  // painel passa a valer imediatamente e não depende de um objeto de revenda
  // que possa ter sido carregado antes da mudança.
  if (revenda?.id) {
    const atual = await get('SELECT modalidade_esim, tipo_revenda FROM revendas WHERE id=?', [revenda.id]);
    if (atual) return normalizarTipoRevenda(atual.modalidade_esim || atual.tipo_revenda || 'PRE_PAGO');
  }
  return normalizarTipoRevenda(revenda?.modalidade_esim || revenda?.tipo_revenda || 'PRE_PAGO');
}
async function precoEsimDaRevenda(revendaId, planoId) {
  const pr = await get('SELECT preco FROM precos_esim_revenda WHERE revenda_id=? AND plano_id=?', [revendaId, planoId]);
  if (pr && Number(pr.preco) > 0) return Number(pr.preco);
  const p = await get('SELECT preco_revenda FROM esim_planos WHERE id=?', [planoId]);
  return Number(p?.preco_revenda || 0);
}
async function escolherRevendaCorreta(rows, numeros=[], fallbackJid='') {
  if (!rows?.length) return null;
  const nums = new Set((numeros || []).flatMap(n => variantesNumero(n)));
  const candidatos = [];
  for (const r of rows) {
    const whats = new Set(variantesNumero(r.whatsapp));
    const jidNums = new Set(variantesNumero(jidToNumber(r.jid)));
    const bateNumero = [...nums].some(n => whats.has(n) || jidNums.has(n));
    const bateJid = !!fallbackJid && r.jid === fallbackJid;
    if (!bateNumero && !bateJid) continue;

    // Bancos antigos podem conter cadastros duplicados do mesmo WhatsApp.
    // Preferimos o cadastro que possui configurações individuais explícitas,
    // pois é nele que o admin alterou preço e pré/pós no painel.
    const cfg = await get('SELECT COUNT(*) AS qtd FROM modalidades_servico_revenda WHERE revenda_id=?', [r.id]);
    const precos = await get('SELECT COUNT(*) AS qtd FROM precos_revenda WHERE revenda_id=?', [r.id]);
    let score = Number(cfg?.qtd || 0) * 20 + Number(precos?.qtd || 0) * 3;
    if (r.modalidade_esim) score += 2;
    if (bateJid) score += 8;
    if ([...nums].some(n => whats.has(n))) score += 12;
    candidatos.push({ r, score });
  }
  candidatos.sort((a,b) => (b.score - a.score) || (Number(b.r.id||0) - Number(a.r.id||0)));
  return candidatos[0]?.r || null;
}
async function getRevendaByJidOrNumber(jid) {
  const numeros = variantesNumero(jidToNumber(jid));
  const rows = await all('SELECT * FROM revendas WHERE status="ATIVA"');
  return escolherRevendaCorreta(rows, numeros, jid);
}
async function getRevendaByMsg(msg, fallbackJid) {
  const numeros = numerosPossiveisDaMensagem(msg, fallbackJid);
  const rows = await all('SELECT * FROM revendas WHERE status="ATIVA"');
  console.log('🔎 BUSCA REVENDA numeros=', numeros.join(','));
  const r = await escolherRevendaCorreta(rows, numeros, fallbackJid);
  if (r) {
    console.log('✅ REVENDA ENCONTRADA:', r.id, r.nome, r.whatsapp);
    return r;
  }
  console.log('❌ REVENDA NÃO ENCONTRADA para:', numeros.join(','));
  return null;
}
function nomeServicoWhatsApp(servico){
  if(!servico) return '';
  const custom=String(servico.nome_exibicao||'').trim();
  if(custom) return custom;
  return String(servico.api_provider||'').toUpperCase()==='DHRU'?dhruNomeServicoPt(servico.nome):String(servico.nome||'');
}
async function nomeCategoriaDhruWhatsApp(categoria){
  const original=String(categoria||'Sem categoria').trim()||'Sem categoria';
  const row=await get(`SELECT display_name FROM dhru_category_display WHERE category=?`,[original]);
  const custom=String(row?.display_name||'').trim();
  return custom||categoriaWhatsAppPt(original,'DHRU');
}
async function nomeCategoriaLocalWhatsApp(){
  return String(await getConfig('whatsapp_categoria_local_nome','Blacklist Brazil')).trim()||'Blacklist Brazil';
}
function categoriaWhatsAppPt(nome, apiProvider='') {
  const original=String(nome||'Serviços').trim()||'Serviços';
  if(String(apiProvider||'').toUpperCase()!=='DHRU') return original;
  let x=original;
  const regras=[
    [/xiaomi/ig,'Xiaomi'],[/apple|iphone/ig,'Apple / iPhone'],[/samsung/ig,'Samsung'],[/huawei/ig,'Huawei'],[/motorola/ig,'Motorola'],
    [/imei\s*(check|checker|checks|services?)/ig,'Consultas de IMEI'],[/imei\s*service(s)?/ig,'Serviços IMEI'],[/check(er)?\s*services?/ig,'Consultas'],
    [/remote\s*service(s)?/ig,'Serviços Remotos'],[/file\s*service(s)?/ig,'Serviços de Arquivo'],[/server\s*service(s)?/ig,'Serviços de Servidor'],
    [/unlock(ing)?/ig,'Desbloqueio'],[/lock\s*code/ig,'Código de Bloqueio'],[/account/ig,'Conta'],[/repair/ig,'Reparo'],
    [/activation/ig,'Ativação'],[/warranty/ig,'Garantia'],[/blacklist/ig,'Blacklist'],[/services?/ig,'Serviços'],
    [/worldwide/ig,'Mundial'],[/brazil/ig,'Brasil'],[/server/ig,'Servidor'],[/carrier/ig,'Operadora'],[/network/ig,'Rede'],[/clean/ig,'Clean']
  ];
  for(const [a,b] of regras)x=x.replace(a,b);
  x=x.replace(/\s{2,}/g,' ').replace(/^\s+|\s+$/g,'');
  return x||original;
}
async function categoriasServicosWhatsApp(){
  const rows=await all(`SELECT categoria,api_provider,COUNT(*) qtd FROM servicos_catalogo WHERE ativo=1 GROUP BY categoria,api_provider ORDER BY CASE WHEN api_provider='DHRU' THEN 1 ELSE 0 END,categoria COLLATE NOCASE`);
  const mapa=[];
  const nomeLocal=await nomeCategoriaLocalWhatsApp();
  for(const r of rows){
    const nomeOriginal=String(r.categoria||'Serviços').trim()||'Serviços';
    const provider=String(r.api_provider||'');
    if(provider.toUpperCase()!=='DHRU'){
      const existente=mapa.find(x=>String(x.api_provider||'').toUpperCase()!=='DHRU');
      if(existente){existente.qtd+=Number(r.qtd||0);existente.categoriasOriginais.push(nomeOriginal);continue;}
      mapa.push({categoria:nomeOriginal,categoriasOriginais:[nomeOriginal],api_provider:provider,nome:nomeLocal,qtd:Number(r.qtd||0)});
      continue;
    }
    const nomePt=await nomeCategoriaDhruWhatsApp(nomeOriginal);
    mapa.push({categoria:nomeOriginal,categoriasOriginais:[nomeOriginal],api_provider:provider,nome:nomePt,qtd:Number(r.qtd||0)});
  }
  return mapa;
}
async function listarServicosTexto(revenda) {
  const cats=await categoriasServicosWhatsApp();
  let texto=`🛠️ *SERVIÇOS*\n\nEscolha uma categoria:\n\n`;
  for(let i=0;i<cats.length;i++) texto+=`${i+1}️⃣ ${cats[i].nome}\n`;
  texto+=`\n0️⃣ ⬅️ Voltar\n\n💬 Digite a opção desejada.`;
  return texto;
}

async function categoriaLocalWhatsAppObjeto(){
  const cats=await categoriasServicosWhatsApp();
  return cats.find(c=>String(c.api_provider||'').toUpperCase()!=='DHRU')||null;
}
async function categoriasDhruWhatsApp(){
  const cats=await categoriasServicosWhatsApp();
  return cats.filter(c=>String(c.api_provider||'').toUpperCase()==='DHRU');
}
async function listarBlacklistBrazilTexto(revenda){
  const cat=await categoriaLocalWhatsAppObjeto();
  const titulo=await nomeCategoriaLocalWhatsApp();
  if(!cat)return `🚫 *${titulo}*\n\nNenhum serviço disponível no momento.\n\n0️⃣ ⬅️ Voltar`;
  const lista=await listarServicosCategoriaTexto(revenda,cat);
  return lista.texto.replace(/^📂 \*[^*]+\*/,`🚫 *${titulo}*`).replace('0️⃣ ⬅️ Categorias','0️⃣ ⬅️ Voltar');
}
async function listarServicosOnlineTexto(){
  const cats=await categoriasDhruWhatsApp();
  let texto=`🌐 *Serviços Online*\n\n`;
  if(!cats.length){
    texto+=`Nenhum serviço online ativo no momento.\n\n0️⃣ ⬅️ Voltar`;
    return texto;
  }
  for(let i=0;i<cats.length;i++)texto+=`${i+1}️⃣ ${cats[i].nome}\n`;
  texto+=`\n🔍 Para buscar um serviço, digite *buscar* seguido do nome.\nExemplo: *buscar xiaomi*\n\n0️⃣ ⬅️ Voltar`;
  return texto;
}
async function buscarServicosOnlineWhatsApp(termo){
  const q=String(termo||'').trim().toLowerCase();
  if(!q)return [];
  const rows=await all(`SELECT * FROM servicos_catalogo WHERE ativo=1 AND COALESCE(api_provider,'')='DHRU' ORDER BY COALESCE(NULLIF(nome_exibicao,''),nome) COLLATE NOCASE`);
  const achados=[];
  for(const r of rows){
    const nome=nomeServicoWhatsApp(r);
    if(String(nome).toLowerCase().includes(q)||String(r.nome||'').toLowerCase().includes(q)){
      achados.push(r);
      if(achados.length>=20)break;
    }
  }
  return achados;
}
async function textoBuscaServicosOnline(rows,revenda,termo){
  let texto=`🔍 *Busca de serviços*\n\nPesquisa: ${String(termo||'').trim()}\n\n`;
  if(!rows.length)return texto+`Nenhum serviço encontrado.\n\n0️⃣ ⬅️ Voltar`;
  for(let i=0;i<rows.length;i++){
    const preco=revenda?await precoDaRevenda(revenda.id,rows[i].id):Number(rows[i].preco_padrao||0);
    texto+=`${i+1}️⃣ ${nomeServicoWhatsApp(rows[i])}\n💰 ${brl(preco)}\n\n`;
  }
  texto+=`0️⃣ ⬅️ Voltar`;
  return texto;
}
async function iniciarServicoWhatsApp(from,cliente,servico){
  if(!servico)return false;
  if(servico.api_provider==='DHRU'){
    const pDhru=await dhruProductForService(servico.id),fsDhru=dhruFieldsUsuario(pDhru);
    const simplesImei=fsDhru.length===1&&String(fsDhru[0]?.name||'').toUpperCase()==='IMEI';
    if(!simplesImei&&fsDhru.length){
      await salvarSessaoPedido(from,{etapa:'dhru_campo',servicoId:servico.id,dhruCampos:fsDhru,dhruValores:[],dhruIndice:0});
      await enviarTexto(from,`🛠 *${nomeServicoWhatsApp(servico)}*\n\n💰 Valor: ${brl(await precoDaRevenda(cliente.id,servico.id))}\n\n${dhruPromptCampo(fsDhru[0],0,fsDhru.length)}\n\n0️⃣ ⬅️ Voltar`);
      return true;
    }
  }
  await salvarSessaoPedido(from,{etapa:'entrada',servicoId:servico.id});
  const tipo=normalizarTipoEntrada(servico.tipo_entrada);
  if(tipo==='IMEI')await enviarTexto(from,`📱 Informe o IMEI:\n\nPode enviar de 1 até 5 IMEIs. O sistema corrige automaticamente espaços, pontos, traços e símbolos.`);
  else await enviarTexto(from,`${iconeEntradaServico(servico)} Informe o ${labelEntradaServico(servico)}:`);
  return true;
}
async function enviarMenuHistoricoWhatsApp(from){
  await enviarTexto(from,`📋 *Histórico*\n\n1️⃣ ⏳ Em processo\n2️⃣ ✅ Concluídos\n3️⃣ ❌ Cancelados\n4️⃣ 📚 Todos os pedidos\n\n0️⃣ ⬅️ Voltar`);
}
async function enviarHistoricoRevendaFiltrado(from,revenda,filtro='TODOS'){
  let where='revenda_id=?',params=[revenda.id],titulo='Todos os pedidos';
  if(filtro==='PROCESSO'){where+=' AND status IN ("PENDENTE","EM PROCESSO")';titulo='Em processo';}
  else if(filtro==='FINALIZADO'){where+=' AND status="FINALIZADO"';titulo='Concluídos';}
  else if(filtro==='CANCELADO'){where+=' AND status="CANCELADO"';titulo='Cancelados';}
  const rows=await all(`SELECT * FROM pedidos WHERE ${where} ORDER BY id DESC LIMIT 15`,params);
  let txt=`📋 *${titulo}*\n\n`;
  if(!rows.length)txt+='Nenhum pedido encontrado.\n\n';
  for(const p of rows){
    const statusIcon=p.status==='FINALIZADO'?'✅':p.status==='CANCELADO'?'❌':p.status==='EM PROCESSO'?'🔄':'⏳';
    txt+=`📦 Pedido #${p.id}\n🛠️ ${p.servico_nome}\n📱 ${p.imei||p.entrada_valor||'-'}\n💰 ${brl(p.valor)}\n📍 ${statusIcon} ${p.status}\n\n`;
  }
  txt+='0️⃣ ⬅️ Voltar';
  await enviarTexto(from,txt.trim());
}
async function enviarMenuMinhaContaWhatsApp(from,revenda){
  const atual=await get('SELECT * FROM revendas WHERE id=?',[revenda.id])||revenda;
  await enviarTexto(from,`👤 *Minha conta*\n\n👤 Nome: ${atual.nome}\n💰 Saldo: ${brl(atual.saldo)}\n\n1️⃣ Meus dados\n2️⃣ Meus pedidos\n3️⃣ Meu PIX\n\n0️⃣ ⬅️ Voltar`);
}
async function enviarDadosContaWhatsApp(from,revenda){
  const atual=await get('SELECT * FROM revendas WHERE id=?',[revenda.id])||revenda;
  const p=await get('SELECT COUNT(*) qtd FROM pedidos WHERE revenda_id=? AND status IN ("PENDENTE","EM PROCESSO")',[atual.id]);
  await enviarTexto(from,`👤 *Meus dados*\n\n👤 Nome: ${atual.nome}\n💰 Saldo: ${brl(atual.saldo)}\n📦 Pedidos em aberto: ${Number(p?.qtd||0)}\n🏷 Perfil: REVENDA\n\n0️⃣ ⬅️ Voltar`);
}
