app.post('/admin/whatsapp/status/publicar', async (req, res) => {
  try {
    const texto = String(req.body.texto || '').trim().slice(0,4000);
    let imagemBuffer = null;
    const data = String(req.body.imageData || '');
    const m = data.match(/^data:image\/(png|jpeg|jpg|webp);base64,(.+)$/i);
    if (m) imagemBuffer = Buffer.from(m[2], 'base64');
    if (!texto && !imagemBuffer) throw new Error('Digite um texto ou escolha uma imagem.');
    const r = await publicarStatusWhatsApp({ texto, imagemBuffer });
    res.redirect('/admin/whatsapp/status?ok=' + encodeURIComponent(`Publicado em ${r.enviados} sessão(ões). Audiência: ${r.audiencia}. Falhas: ${r.falhas}.`));
  } catch (e) { res.redirect('/admin/whatsapp/status?erro=' + encodeURIComponent(e.message)); }
});

